// Peer comparison for the shared radar (Performance summary, Post summary).
// Every number is computed in build.js from the seeded cohort in data/peers.js;
// this module only names the two entry points and the info drawer copy.
import { accountRadar, postRadar, aiInfo } from './build.js';
import { COHORT } from '../data/peers.js';

export const accountPeerComparison = () => accountRadar();
export const videoPeerComparison = (post) => postRadar(post);

// ⓘ sheet (2026-11-28 Yanice): Generated by AI (+ what "Ahead of X%" on the radar labels means) · Safety and privacy · Data period
// The status chips (Strong / Typical / Room to grow) are gone from the radar, so the line explains the percentile instead.
export const peerInfo = (scope, period) => {
  const peers = scope === 'post' ? 'similar videos' : 'similar creators';
  return aiInfo({ basis: period, peers, status: `“Ahead of X%” means you did better than X% of ${peers}.` });
};
